import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Button, Card, Form, Input, Label, Message, Step, Table} from 'semantic-ui-react';
import {useNavigate, useParams} from 'react-router-dom';
import {API, copy, showError, showInfo, showSuccess, verifyJSON,} from '../../helpers';
import {CHANNEL_OPTIONS} from '../../constants';
import {renderChannelTip} from '../../helpers/render';

const MODEL_MAPPING_EXAMPLE = {
  'model-alias': 'original-model-name',
};

function type2secretPrompt(type, t) {
  switch (type) {
    case 15:
      return t('channel.edit.key_prompts.zhipu');
    case 18:
      return t('channel.edit.key_prompts.spark');
    case 22:
      return t('channel.edit.key_prompts.fastgpt');
    case 23:
      return t('channel.edit.key_prompts.tencent');
    default:
      return t('channel.edit.key_prompts.default');
  }
}

const EditChannel = () => {
  const { t } = useTranslation();
  const params = useParams();
  const navigate = useNavigate();
  const channelId = params.id;
  const isEdit = channelId !== undefined;
  const [loading, setLoading] = useState(isEdit);
  const handleCancel = () => {
    navigate('/channel');
  };

  const originInputs = {
    name: '',
    type: 1,
    key: '',
    multi_key_mode: 0,
    keys: [],
    base_url: '',
    other: '',
    model_mapping: '',
    models: [],
    groups: ['default'],
  };
  const [batch, setBatch] = useState(false);
  const [step, setStep] = useState(1); // 1=基本信息, 2=密钥配置, 3=模型选择
  const [inputs, setInputs] = useState(originInputs);
  const [modelOptions, setModelOptions] = useState([]);
  const [groupOptions, setGroupOptions] = useState([]);
  const [customModel, setCustomModel] = useState('');
  const [fetchingModels, setFetchingModels] = useState(false);
  // 模型别名列表: [{original: string, alias: string}]
  // alias 为空时使用原始名;alias !== original 时生成 model_mapping
  const [modelAliases, setModelAliases] = useState([]);
  const [config, setConfig] = useState({
    region: '',
    sk: '',
    ak: '',
    user_id: '',
    vertex_ai_project_id: '',
    vertex_ai_adc: '',
  });
  const handleInputChange = (e, { name, value }) => {
    setInputs((inputs) => ({ ...inputs, [name]: value }));
  };

  const handleConfigChange = (e, { name, value }) => {
    setConfig((inputs) => ({ ...inputs, [name]: value }));
  };

  // —— 多 Key 列表操作 ——
  const addKey = () => {
    setInputs((prev) => ({
      ...prev,
      keys: [...prev.keys, { key_value: '', remark: '', priority: 0, daily_quota_limit: 0, quota_reset_rule: '', status: 1 }],
    }));
  };
  const removeKey = (index) => {
    setInputs((prev) => ({ ...prev, keys: prev.keys.filter((_, i) => i !== index) }));
  };
  const updateKeyField = (index, field, value) => {
    setInputs((prev) => {
      let keys = [...prev.keys];
      keys[index] = { ...keys[index], [field]: value };
      return { ...prev, keys };
    });
  };

  const loadChannel = async () => {
    let res = await API.get(`/api/channel/${channelId}`);
    const { success, message, data } = res.data;
    if (success) {
      if (data.models === '') {
        data.models = [];
      } else {
        data.models = data.models.split(',');
      }
      if (data.group === '') {
        data.groups = [];
      } else {
        data.groups = data.group.split(',');
      }
      // 从 models + model_mapping 反向解析 modelAliases
      let mapping = {};
      if (data.model_mapping !== '') {
        try {
          mapping = JSON.parse(data.model_mapping);
        } catch (e) {
          // model_mapping 格式错误,忽略
        }
      }
      const mappingValues = new Set(Object.values(mapping));
      let consumedKeys = new Set();
      let originalsFromKeys = new Set();
      let aliases = [];
      // 第一遍: 处理 mapping key(别名)
      data.models.forEach((model) => {
        if (mapping[model]) {
          aliases.push({ original: mapping[model], alias: model });
          consumedKeys.add(model);
          originalsFromKeys.add(mapping[model]);
        }
      });
      // 第二遍: 处理非 key 的 model,跳过已被 key 引用为 original 的 value(旧数据兼容)
      data.models.forEach((model) => {
        if (!mapping[model]) {
          if (originalsFromKeys.has(model)) {
            return;
          }
          aliases.push({ original: model, alias: '' });
        }
      });
      // 检测未被消费的 mapping key(旧数据中 key 不在 models 里)
      let unconsumedCount = Object.keys(mapping).length - consumedKeys.size;
      if (unconsumedCount > 0) {
        showInfo(t('channel.edit.messages.mapping_keys_ignored', { count: unconsumedCount }));
      }
      setModelAliases(aliases);
      // inputs.models 设为原始名,供下拉框使用
      data.models = aliases.map((a) => a.original);
      // 多 key 模式：额外拉取该渠道的 key 列表
      if (data.multi_key_mode && data.multi_key_mode !== 0) {
        try {
          let keysRes = await API.get(`/api/channel/${channelId}/keys/status`);
          if (keysRes.data.success && Array.isArray(keysRes.data.data)) {
            data.keys = keysRes.data.data.map((k) => ({
              key_value: k.key_value || '',
              remark: k.remark || '',
              priority: k.priority || 0,
              daily_quota_limit: k.daily_quota_limit || 0,
              quota_reset_rule: k.quota_reset_rule || '',
              status: k.status || 1,
            }));
          }
        } catch (e) {
          // 拉取 key 列表失败不阻断编辑
        }
      } else {
        data.keys = [];
      }
      // 防御性归一化：避免 API 失败/异常导致 keys 或 multi_key_mode 为 undefined
      data.keys = data.keys || [];
      data.multi_key_mode = data.multi_key_mode || 0;
      setInputs(data);
      if (data.config !== '') {
        setConfig(JSON.parse(data.config));
      }
    } else {
      showError(message);
    }
    setLoading(false);
  };

  const fetchUpstreamModels = async () => {
    setFetchingModels(true);
    try {
      let res;
      if (channelId) {
        // 已保存渠道：用 GET /fetch_models/:id
        res = await API.get(`/api/channel/fetch_models/${channelId}`);
      } else {
        // 新建渠道：用 POST /fetch_models，传 {base_url, key, type}
        if (!inputs.base_url && !inputs.key) {
          showInfo(t('channel.edit.messages.fetch_need_config'));
          return;
        }
        res = await API.post('/api/channel/fetch_models', {
          base_url: inputs.base_url,
          key: inputs.key,
          type: inputs.type,
        });
      }
      const { success, message, data } = res.data;
      if (success) {
        if (data.length === 0) {
          showInfo(t('channel.edit.messages.fetch_empty'));
          return;
        }
        // 合并到当前已选模型(去重)
        let existingModels = new Set(inputs.models);
        let newModels = [];
        data.forEach((model) => {
          if (!existingModels.has(model)) {
            newModels.push(model);
          }
        });
        let allModels = [...inputs.models, ...newModels];
        handleInputChange(null, { name: 'models', value: allModels });
        // 同步 modelAliases: 新模型添加空别名条目
        if (newModels.length > 0) {
          setModelAliases((prev) => [
            ...prev,
            ...newModels.map((m) => ({ original: m, alias: '' })),
          ]);
        }
        showSuccess(t('channel.edit.messages.fetch_success', { total: data.length, added: newModels.length }));
      } else {
        showError(message);
      }
    } catch (error) {
      showError(error.message);
    } finally {
      setFetchingModels(false);
    }
  };

  const fetchGroups = async () => {
    try {
      let res = await API.get(`/api/group/`);
      setGroupOptions(
        res.data.data.map((group) => ({
          key: group,
          text: group,
          value: group,
        }))
      );
    } catch (error) {
      showError(error.message);
    }
  };

  useEffect(() => {
    let localModelOptions = [];
    inputs.models.forEach((model) => {
      if (!localModelOptions.find((option) => option.key === model)) {
        localModelOptions.push({
          key: model,
          text: model,
          value: model,
        });
      }
    });
    setModelOptions(localModelOptions);
  }, [inputs.models]);

  // modelAliases 变化时自动同步 model_mapping 文本框(只读展示)
  useEffect(() => {
    let mapping = {};
    modelAliases.forEach((a) => {
      if (a.alias.trim() !== '' && a.alias.trim() !== a.original) {
        mapping[a.alias.trim()] = a.original;
      }
    });
    const mappingStr =
      Object.keys(mapping).length > 0 ? JSON.stringify(mapping, null, 2) : '';
    setInputs((prev) =>
      prev.model_mapping === mappingStr
        ? prev
        : { ...prev, model_mapping: mappingStr }
    );
  }, [modelAliases]);

  useEffect(() => {
    if (isEdit) {
      loadChannel().then();
    }
    fetchGroups().then();
  }, []);

  const submit = async () => {
    if (inputs.key === '') {
      if (config.ak !== '' && config.sk !== '' && config.region !== '') {
        inputs.key = `${config.ak}|${config.sk}|${config.region}`;
      } else if (
        config.region !== '' &&
        config.vertex_ai_project_id !== '' &&
        config.vertex_ai_adc !== ''
      ) {
        inputs.key = `${config.region}|${config.vertex_ai_project_id}|${config.vertex_ai_adc}`;
      }
    }
    if (!isEdit && (inputs.name === '' || inputs.key === '')) {
      showInfo(t('channel.edit.messages.name_required'));
      return;
    }
    if (inputs.type !== 43 && inputs.models.length === 0) {
      showInfo(t('channel.edit.messages.models_required'));
      return;
    }
    if (inputs.model_mapping !== '' && !verifyJSON(inputs.model_mapping)) {
      showInfo(t('channel.edit.messages.model_mapping_invalid'));
      return;
    }
    let localInputs = { ...inputs };
    // 多 key 模式：组装 keys 数组，保留首个 key 到 key 字段兼容
    if (localInputs.multi_key_mode && localInputs.multi_key_mode !== 0 && localInputs.keys && localInputs.keys.length > 0) {
      let validKeys = localInputs.keys.filter((k) => k.key_value && k.key_value.trim() !== '');
      if (validKeys.length === 0) {
        showInfo(t('channel.edit.messages.keys_required', '请至少添加一个有效密钥！'));
        return;
      }
      localInputs.keys = validKeys.map((k) => ({
        key_value: k.key_value,
        remark: k.remark || '',
        priority: k.priority || 0,
        daily_quota_limit: k.daily_quota_limit || 0,
        quota_reset_rule: k.quota_reset_rule || '',
      }));
      if (validKeys.length > 0) {
        localInputs.key = validKeys[0].key_value;
      }
    }
    if (localInputs.key === 'undefined|undefined|undefined') {
      localInputs.key = ''; // prevent potential bug
    }
    if (localInputs.base_url && localInputs.base_url.endsWith('/')) {
      localInputs.base_url = localInputs.base_url.slice(
        0,
        localInputs.base_url.length - 1
      );
    }
    if (localInputs.type === 3 && localInputs.other === '') {
      localInputs.other = '2024-03-01-preview';
    }
    // 从 modelAliases 生成最终 models 和 model_mapping
    // models 存别名(有别名时)或原始名(无别名时)
    // model_mapping 存 {别名: 原始名},仅当 alias !== original 时
    // 校验: 禁止逗号(破坏 models 字段分隔)、禁止重复对外名
    let finalModels = [];
    let mapping = {};
    let seenNames = new Set();
    for (let i = 0; i < modelAliases.length; i++) {
      const a = modelAliases[i];
      const alias = a.alias.trim();
      if (alias.includes(',')) {
        showError(t('channel.edit.messages.alias_invalid_comma'));
        return;
      }
      const finalName = alias !== '' ? alias : a.original;
      if (seenNames.has(finalName)) {
        showError(t('channel.edit.messages.alias_duplicate', { name: finalName }));
        return;
      }
      seenNames.add(finalName);
      finalModels.push(finalName);
      if (alias !== '' && alias !== a.original) {
        mapping[alias] = a.original;
      }
    }
    localInputs.models = finalModels.join(',');
    localInputs.model_mapping =
      Object.keys(mapping).length > 0 ? JSON.stringify(mapping, null, 2) : '';
    localInputs.group = localInputs.groups.join(',');
    localInputs.config = JSON.stringify(config);
    let res;
    if (isEdit) {
      res = await API.put(`/api/channel/`, {
        ...localInputs,
        id: parseInt(channelId),
      });
    } else {
      res = await API.post(`/api/channel/`, localInputs);
    }
    const { success, message } = res.data;
    if (success) {
      if (isEdit) {
        showSuccess(t('channel.edit.messages.update_success'));
      } else {
        showSuccess(t('channel.edit.messages.create_success'));
        setInputs(originInputs);
      }
    } else {
      showError(message);
    }
  };

  const addCustomModel = () => {
    if (customModel.trim() === '') return;
    if (inputs.models.includes(customModel)) return;
    let localModels = [...inputs.models];
    localModels.push(customModel);
    let localModelOptions = [];
    localModelOptions.push({
      key: customModel,
      text: customModel,
      value: customModel,
    });
    setModelOptions((modelOptions) => {
      return [...modelOptions, ...localModelOptions];
    });
    setCustomModel('');
    handleInputChange(null, { name: 'models', value: localModels });
    // 同步 modelAliases
    setModelAliases((prev) => [...prev, { original: customModel, alias: '' }]);
  };

  // 下拉框增删模型时同步 modelAliases
  const handleModelsChange = (e, { value }) => {
    const newModels = value;
    const oldModels = inputs.models;
    // 找出新增的模型
    const added = newModels.filter((m) => !oldModels.includes(m));
    // 找出删除的模型
    const removed = oldModels.filter((m) => !newModels.includes(m));
    setModelAliases((prev) => {
      let result = prev.filter((a) => !removed.includes(a.original));
      result = [...result, ...added.map((m) => ({ original: m, alias: '' }))];
      return result;
    });
    handleInputChange(null, { name: 'models', value: newModels });
  };

  // 更新某行的别名
  const updateModelAlias = (index, alias) => {
    setModelAliases((prev) => {
      let result = [...prev];
      result[index] = { ...result[index], alias };
      return result;
    });
  };

  // 删除某行(同时从 models 中移除)
  const removeModelAlias = (index) => {
    const model = modelAliases[index].original;
    setModelAliases((prev) => prev.filter((_, i) => i !== index));
    handleInputChange(null, {
      name: 'models',
      value: inputs.models.filter((m) => m !== model),
    });
  };

  // ====== 渲染：基本信息 Section（编辑模式 + 向导 Step 1 共用） ======
  const renderBasicSection = () => (
    <>
      <Form.Field>
        <Form.Select
          label={t('channel.edit.type')}
          name='type'
          required
          search
          options={CHANNEL_OPTIONS}
          value={inputs.type}
          onChange={handleInputChange}
        />
      </Form.Field>
      <Form.Field>
        <Form.Input
          label={t('channel.edit.name')}
          name='name'
          placeholder={t('channel.edit.name_placeholder')}
          onChange={handleInputChange}
          value={inputs.name}
          required
        />
      </Form.Field>
      {renderChannelTip(inputs.type)}

      {/* Azure / Custom / 其他类型特殊字段 */}
      {inputs.type === 3 && (
        <>
          <Message>
            注意，<strong>模型部署名称必须和模型名称保持一致</strong>，
            因为 One API 会把请求体中的 model 参数替换为你的部署名称（模型名称中的点会被剔除）。
          </Message>
          <Form.Field>
            <Form.Input
              label='AZURE_OPENAI_ENDPOINT'
              name='base_url'
              placeholder='请输入 AZURE_OPENAI_ENDPOINT，例如：https://docs-test-001.openai.azure.com'
              onChange={handleInputChange}
              value={inputs.base_url}
              autoComplete='new-password'
            />
          </Form.Field>
          <Form.Field>
            <Form.Input
              label='默认 API 版本'
              name='other'
              placeholder='请输入默认 API 版本，例如：2024-03-01-preview'
              onChange={handleInputChange}
              value={inputs.other}
              autoComplete='new-password'
            />
          </Form.Field>
        </>
      )}
      {inputs.type === 8 && (
        <Form.Field>
          <Form.Input
            required
            label={t('channel.edit.proxy_url')}
            name='base_url'
            placeholder={t('channel.edit.proxy_url_placeholder')}
            onChange={handleInputChange}
            value={inputs.base_url}
            autoComplete='new-password'
          />
        </Form.Field>
      )}
      {inputs.type === 50 && (
        <Form.Field>
          <Form.Input
            required
            label={t('channel.edit.base_url')}
            name='base_url'
            placeholder={t('channel.edit.base_url_placeholder')}
            onChange={handleInputChange}
            value={inputs.base_url}
            autoComplete='new-password'
          />
        </Form.Field>
      )}
      {inputs.type === 18 && (
        <Form.Field>
          <Form.Input
            label={t('channel.edit.spark_version')}
            name='other'
            placeholder={t('channel.edit.spark_version_placeholder')}
            onChange={handleInputChange}
            value={inputs.other}
            autoComplete='new-password'
          />
        </Form.Field>
      )}
      {inputs.type === 21 && (
        <Form.Field>
          <Form.Input
            label={t('channel.edit.knowledge_id')}
            name='other'
            placeholder={t('channel.edit.knowledge_id_placeholder')}
            onChange={handleInputChange}
            value={inputs.other}
            autoComplete='new-password'
          />
        </Form.Field>
      )}
      {inputs.type === 17 && (
        <Form.Field>
          <Form.Input
            label={t('channel.edit.plugin_param')}
            name='other'
            placeholder={t('channel.edit.plugin_param_placeholder')}
            onChange={handleInputChange}
            value={inputs.other}
            autoComplete='new-password'
          />
        </Form.Field>
      )}
      {inputs.type === 34 && <Message>{t('channel.edit.coze_notice')}</Message>}
      {inputs.type === 40 && (
        <Message>
          {t('channel.edit.douban_notice')}
          <a target='_blank' href='https://console.volcengine.com/ark/region:ark+cn-beijing/endpoint'>
            {t('channel.edit.douban_notice_link')}
          </a>
          {t('channel.edit.douban_notice_2')}
        </Message>
      )}
      {inputs.type !== 3 && inputs.type !== 33 && inputs.type !== 8 && inputs.type !== 50 && inputs.type !== 22 && (
        <Form.Field>
          <Form.Input
            label={t('channel.edit.proxy_url')}
            name='base_url'
            placeholder={t('channel.edit.proxy_url_placeholder')}
            onChange={handleInputChange}
            value={inputs.base_url}
            autoComplete='new-password'
          />
        </Form.Field>
      )}
      {inputs.type === 22 && (
        <Form.Field>
          <Form.Input
            label='私有部署地址'
            name='base_url'
            placeholder='请输入私有部署地址，格式为：https://fastgpt.run/api/openapi'
            onChange={handleInputChange}
            value={inputs.base_url}
            autoComplete='new-password'
          />
        </Form.Field>
      )}
    </>
  );

  // ====== 渲染：密钥 Section（编辑模式 + 向导 Step 2 共用） ======
  const renderKeySection = () => (
    <>
      {/* 多 Key 模式选择 */}
      {inputs.type !== 33 && inputs.type !== 42 && (
        <Form.Field>
          <Form.Dropdown
            label={t('channel.edit.multi_key_mode', '多 Key 模式')}
            name='multi_key_mode'
            selection
            value={inputs.multi_key_mode}
            onChange={handleInputChange}
            options={[
              { key: 0, text: t('channel.edit.multi_key_off', '关闭（单 key 兼容）'), value: 0 },
              { key: 1, text: t('channel.edit.multi_key_priority', '优先级 + 故障转移'), value: 1 },
              { key: 2, text: t('channel.edit.multi_key_prefix_shard', '前缀分片'), value: 2 },
              { key: 3, text: t('channel.edit.multi_key_polling', '轮询'), value: 3 },
              { key: 4, text: t('channel.edit.multi_key_lur', '最少已用比例优先'), value: 4 },
            ]}
          />
        </Form.Field>
      )}
      {/* 多 Key 表格 — 按设计稿 19:167 精确还原（自适应宽度） */}
      {inputs.type !== 33 && inputs.type !== 42 && inputs.multi_key_mode !== 0 && (
        <Form.Field>
          <div style={{ marginBottom: '8px', display: 'flex', alignItems: 'center', gap: '8px' }}>
            <label style={{ color: 'var(--aurora-text)', fontSize: '13px', fontWeight: 500 }}>
              {t('channel.edit.keys_list', '密钥列表')}
            </label>
            <Label size='tiny' style={{ background: 'rgba(184,111,5,0.15)', color: '#B86F05' }}>
              {inputs.keys.length}
            </Label>
          </div>

          {inputs.keys.length > 0 && (
            <div className='aurora-key-table-wrap'>
              {/* 表头 */}
              <div className='aurora-key-table-header'>
                <span className='aurora-key-th-key'>{t('channel.edit.key_value', '密钥')}</span>
                <span className='aurora-key-th-remark'>{t('channel.edit.key_remark', '备注')}</span>
                <span className='aurora-key-th-priority'>{t('channel.edit.key_priority', '优先级')}</span>
                <span className='aurora-key-th-quota'>{t('channel.edit.key_daily_quota', '每日配额')}</span>
                <span className='aurora-key-th-reset'>{t('channel.edit.key_reset_rule', '重置时刻')}</span>
                <span className='aurora-key-th-action'>{t('channel.edit.alias_actions', '操作')}</span>
              </div>
              {/* 数据行 */}
              {inputs.keys.map((k, index) => (
                <div className='aurora-key-table-row' key={index + '_' + k.key_value}>
                  <div className='aurora-key-cell-key'>
                    <input
                      required
                      value={k.key_value}
                      onChange={(e) => updateKeyField(index, 'key_value', e.target.value)}
                      placeholder='sk-...'
                      autoComplete='new-password'
                      style={{ width: '100%' }}
                    />
                  </div>
                  <div className='aurora-key-cell-remark'>
                    <input
                      value={k.remark}
                      onChange={(e) => updateKeyField(index, 'remark', e.target.value)}
                      placeholder='—'
                      style={{ width: '100%' }}
                    />
                  </div>
                  <div className='aurora-key-cell-priority'>
                    <input
                      type='number'
                      value={k.priority}
                      onChange={(e) => updateKeyField(index, 'priority', parseInt(e.target.value) || 0)}
                      style={{ width: '100%', textAlign: 'center' }}
                    />
                  </div>
                  <div className='aurora-key-cell-quota'>
                    <input
                      type='number'
                      value={k.daily_quota_limit}
                      onChange={(e) => updateKeyField(index, 'daily_quota_limit', parseInt(e.target.value) || 0)}
                      placeholder='0'
                      style={{ width: '100%' }}
                    />
                  </div>
                  <div className='aurora-key-cell-reset'>
                    <select
                      value={k.quota_reset_rule}
                      onChange={(e) => updateKeyField(index, 'quota_reset_rule', e.target.value)}
                      style={{
                        width: '100%', height: 36, borderRadius: 6,
                        background: 'rgba(255,255,255,0.05)', border: '1px solid rgba(255,255,255,0.1)',
                        color: 'var(--aurora-text)', fontSize: 12, padding: '0 8px',
                      }}
                    >
                      <option value=''>{t('channel.edit.no_reset', '不重置')}</option>
                      <option value='00:00'>00:00</option>
                      <option value='04:00'>04:00</option>
                      <option value='08:00'>08:00</option>
                      <option value='12:00'>12:00</option>
                      <option value='16:00'>16:00</option>
                      <option value='20:00'>20:00</option>
                    </select>
                  </div>
                  <div className='aurora-key-cell-action'>
                    <button
                      className='aurora-key-delete-btn'
                      type='button'
                      onClick={() => removeKey(index)}
                    >
                      {t('channel.edit.remove_key', '删除')}
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* 添加密钥按钮 */}
          <button type='button' className='aurora-key-add-btn' onClick={addKey}>
            + {t('channel.edit.add_key', '添加密钥')}
          </button>

          {/* 重置时刻提示 */}
          <div className='aurora-key-hint'>
            {t('channel.edit.reset_hint', '重置时刻按 4 小时一档：00:00 / 04:00 / 08:00 / 12:00 / 16:00 / 20:00 / 不重置；每日配额 0 表示不限')}
          </div>

          {inputs.keys.length === 0 && (
            <div style={{ color: 'var(--aurora-text-muted)', fontSize: '13px', padding: '16px 0' }}>
              {t('channel.edit.no_key_hint', '暂无密钥，点击「添加密钥」新建')}
            </div>
          )}
        </Form.Field>
      )}
      {/* 单 Key 模式 */}
      {inputs.type !== 33 && inputs.type !== 42 && inputs.multi_key_mode === 0 && (
        batch ? (
          <Form.Field>
            <Form.TextArea
              label={t('channel.edit.key')}
              name='key'
              required
              placeholder={t('channel.edit.batch_placeholder')}
              onChange={handleInputChange}
              value={inputs.key}
              style={{ minHeight: 150, fontFamily: 'JetBrains Mono, Consolas' }}
              autoComplete='new-password'
            />
          </Form.Field>
        ) : (
          <Form.Field>
            <Form.Input
              label={t('channel.edit.key')}
              name='key'
              required
              placeholder={type2secretPrompt(inputs.type, t)}
              onChange={handleInputChange}
              value={inputs.key}
              autoComplete='new-password'
            />
          </Form.Field>
        )
      )}
      {inputs.type !== 33 && !isEdit && inputs.multi_key_mode === 0 && (
        <Form.Checkbox
          checked={batch}
          label={t('channel.edit.batch')}
          name='batch'
          onChange={() => setBatch(!batch)}
        />
      )}
      {/* AWS / Vertex AI / Coze / Lambda 特殊配置 */}
      {inputs.type === 33 && (
        <Form.Field>
          <Form.Input label='Region' name='region' required placeholder={t('channel.edit.aws_region_placeholder')} onChange={handleConfigChange} value={config.region} autoComplete='' />
          <Form.Input label='AK' name='ak' required placeholder={t('channel.edit.aws_ak_placeholder')} onChange={handleConfigChange} value={config.ak} autoComplete='' />
          <Form.Input label='SK' name='sk' required placeholder={t('channel.edit.aws_sk_placeholder')} onChange={handleConfigChange} value={config.sk} autoComplete='' />
        </Form.Field>
      )}
      {inputs.type === 42 && (
        <Form.Field>
          <Form.Input label='Region' name='region' required placeholder={t('channel.edit.vertex_region_placeholder')} onChange={handleConfigChange} value={config.region} autoComplete='' />
          <Form.Input label={t('channel.edit.vertex_project_id')} name='vertex_ai_project_id' required placeholder={t('channel.edit.vertex_project_id_placeholder')} onChange={handleConfigChange} value={config.vertex_ai_project_id} autoComplete='' />
          <Form.Input label={t('channel.edit.vertex_credentials')} name='vertex_ai_adc' required placeholder={t('channel.edit.vertex_credentials_placeholder')} onChange={handleConfigChange} value={config.vertex_ai_adc} autoComplete='' />
        </Form.Field>
      )}
      {inputs.type === 34 && (
        <Form.Input label={t('channel.edit.user_id')} name='user_id' required placeholder={t('channel.edit.user_id_placeholder')} onChange={handleConfigChange} value={config.user_id} autoComplete='' />
      )}
      {inputs.type === 37 && (
        <Form.Field>
          <Form.Input label='Account ID' name='user_id' required placeholder='请输入 Account ID' onChange={handleConfigChange} value={config.user_id} autoComplete='' />
        </Form.Field>
      )}
    </>
  );

  // ====== 渲染：模型映射 Section（编辑模式 + 向导 Step 3 共用） ======
  const renderModelSection = () => (
    <>
      {inputs.type !== 43 && (
        <Form.Field>
          <Form.Dropdown
            label={t('channel.edit.models')}
            placeholder={t('channel.edit.models_placeholder')}
            name='models'
            required
            fluid
            multiple
            search
            onLabelClick={(e, { value }) => { copy(value).then(); }}
            selection
            onChange={handleModelsChange}
            value={inputs.models}
            autoComplete='new-password'
            options={modelOptions}
          />
        </Form.Field>
      )}
      {inputs.type !== 43 && (
        <div style={{ lineHeight: '40px', marginBottom: '12px' }}>
          <Button type={'button'} loading={fetchingModels} disabled={fetchingModels} onClick={fetchUpstreamModels}>
            {t('channel.edit.buttons.fetch_upstream')}
          </Button>
          <Button type={'button'} onClick={() => { handleInputChange(null, { name: 'models', value: [] }); setModelAliases([]); setModelOptions([]); }}>
            {t('channel.edit.buttons.clear')}
          </Button>
          <Input
            action={<Button type={'button'} onClick={addCustomModel}>{t('channel.edit.buttons.add_custom')}</Button>}
            placeholder={t('channel.edit.buttons.custom_placeholder')}
            value={customModel}
            onChange={(e, { value }) => { setCustomModel(value); }}
            onKeyDown={(e) => { if (e.key === 'Enter') { addCustomModel(); e.preventDefault(); } }}
          />
        </div>
      )}
      {inputs.type !== 43 && modelAliases.length > 0 && (
        <Form.Field>
          <label>{t('channel.edit.model_aliases')}</label>
          <p style={{ color: 'var(--aurora-text-muted)', fontSize: '0.85em', marginTop: '-5px' }}>
            {t('channel.edit.model_aliases_hint')}
          </p>
          <Table compact size='small' unstackable>
            <Table.Header>
              <Table.Row>
                <Table.HeaderCell width={7}>{t('channel.edit.alias_original')}</Table.HeaderCell>
                <Table.HeaderCell width={7}>{t('channel.edit.alias_name')}</Table.HeaderCell>
                <Table.HeaderCell width={2}>{t('channel.edit.alias_actions')}</Table.HeaderCell>
              </Table.Row>
            </Table.Header>
            <Table.Body>
              {modelAliases.map((item, index) => (
                <Table.Row key={index}>
                  <Table.Cell>{item.original}</Table.Cell>
                  <Table.Cell>
                    <Input fluid size='small' placeholder={item.original} value={item.alias} onChange={(e, { value }) => updateModelAlias(index, value)} />
                  </Table.Cell>
                  <Table.Cell>
                    <Button size='mini' negative type='button' onClick={() => removeModelAlias(index)}>
                      {t('channel.edit.alias_remove')}
                    </Button>
                  </Table.Cell>
                </Table.Row>
              ))}
            </Table.Body>
          </Table>
        </Form.Field>
      )}
    </>
  );

  // ====== 渲染：高级设置 Section（编辑模式专用） ======
  const renderAdvancedSection = () => (
    <Form.Group widths='equal'>
      <Form.Input
        label={t('channel.edit.priority', '优先级')}
        name='priority'
        type='number'
        value={inputs.priority}
        onChange={handleInputChange}
      />
      <Form.Input
        label={t('channel.edit.weight', '权重')}
        name='weight'
        type='number'
        value={inputs.weight}
        onChange={handleInputChange}
      />
      <Form.Dropdown
        label={t('channel.edit.group', '分组')}
        placeholder={t('channel.edit.group_placeholder')}
        name='groups'
        required
        fluid
        multiple
        selection
        allowAdditions
        additionLabel={t('channel.edit.group_addition')}
        onChange={handleInputChange}
        value={inputs.groups}
        autoComplete='new-password'
        options={groupOptions}
      />
    </Form.Group>
  );

  // ====== 编辑模式：单页弹窗（设计稿 3:2379） ======
  if (isEdit) {
    return (
      <div className='aurora-dashboard'>
        <Card fluid className='aurora-chart-card aurora-edit-channel-modal'>
          <Card.Content>
            {/* HeaderBar */}
            <div className='aurora-edit-channel-header'>
              <span className='aurora-edit-channel-title'>
                {t('channel.edit.title_edit')}
              </span>
            </div>

            <Form loading={loading} autoComplete='new-password'>
              {/* Section 1: 基本信息 */}
              <div className='aurora-setting-section-header'>
                <span className='aurora-setting-section-title'>
                  {t('channel.edit.section_basic', '基本信息')}
                </span>
              </div>
              {renderBasicSection()}

              {/* Section 2: 密钥管理 */}
              <div className='aurora-setting-section-header' style={{ marginTop: 'var(--space-5)' }}>
                <span className='aurora-setting-section-title'>
                  {t('channel.edit.section_key', '密钥管理')}
                </span>
              </div>
              {renderKeySection()}

              {/* Section 3: 模型映射 */}
              <div className='aurora-setting-section-header' style={{ marginTop: 'var(--space-5)' }}>
                <span className='aurora-setting-section-title'>
                  {t('channel.edit.section_model', '模型映射')}
                </span>
              </div>
              {renderModelSection()}

              {/* Section 4: 高级设置 */}
              <div className='aurora-setting-section-header' style={{ marginTop: 'var(--space-5)' }}>
                <span className='aurora-setting-section-title'>
                  {t('channel.edit.section_advanced', '高级设置')}
                </span>
              </div>
              {renderAdvancedSection()}
            </Form>

            {/* FooterBar（设计稿：提示 + 取消 + 金色保存按钮） */}
            <div className='aurora-edit-channel-footer'>
              <span className='aurora-edit-channel-hint'>
                {t('channel.edit.footer_hint', '修改后需重新测试渠道可用性')}
              </span>
              <div className='aurora-edit-channel-actions'>
                <Button type='button' basic onClick={handleCancel}>
                  {t('channel.edit.buttons.cancel')}
                </Button>
                <button
                  type='button'
                  className='aurora-save-btn'
                  onClick={submit}
                  disabled={loading}
                >
                  {t('channel.edit.buttons.submit')}
                </button>
              </div>
            </div>
          </Card.Content>
        </Card>
      </div>
    );
  }

  // ====== 添加模式：3步向导（设计稿 3:2660） ======
  return (
    <div className='aurora-dashboard'>
      <Card fluid className='aurora-chart-card'>
        <Card.Content>
          <div className='aurora-edit-channel-header'>
            <span className='aurora-edit-channel-title'>
              {t('channel.edit.title_create')}
            </span>
            <Label style={{ background: 'var(--aurora-accent)', color: '#fff' }}>
              {t('channel.edit.wizard.badge', '向导模式')}
            </Label>
          </div>

          {/* 步骤指示器 */}
          <div style={{ display: 'flex', justifyContent: 'center', marginBottom: '24px', marginTop: '16px' }}>
            <Step.Group widths={3}>
              <Step active={step === 1} completed={step > 1} onClick={() => setStep(1)} style={{ cursor: 'pointer' }}>
                <Step.Content>
                  <Step.Title>{t('channel.edit.wizard.step1_title')}</Step.Title>
                  <Step.Description>{t('channel.edit.wizard.step1_desc')}</Step.Description>
                </Step.Content>
              </Step>
              <Step active={step === 2} completed={step > 2} disabled={step < 1} onClick={() => step > 1 && setStep(2)} style={{ cursor: step > 1 ? 'pointer' : 'default' }}>
                <Step.Content>
                  <Step.Title>{t('channel.edit.wizard.step2_title')}</Step.Title>
                  <Step.Description>{t('channel.edit.wizard.step2_desc')}</Step.Description>
                </Step.Content>
              </Step>
              <Step active={step === 3} disabled={step < 2} onClick={() => step > 2 && setStep(3)} style={{ cursor: step > 2 ? 'pointer' : 'default' }}>
                <Step.Content>
                  <Step.Title>{t('channel.edit.wizard.step3_title')}</Step.Title>
                  <Step.Description>{t('channel.edit.wizard.step3_desc')}</Step.Description>
                </Step.Content>
              </Step>
            </Step.Group>
          </div>

          <Form loading={loading} autoComplete='new-password'>
            {step === 1 && renderBasicSection()}
            {step === 2 && renderKeySection()}
            {step === 3 && renderModelSection()}
          </Form>

          {/* 步骤导航按钮 */}
          <div className='aurora-edit-channel-footer'>
            <Button basic onClick={handleCancel}>
              {t('channel.edit.buttons.cancel')}
            </Button>
            <div>
              {step > 1 && (
                <Button basic onClick={() => setStep(step - 1)} style={{ marginRight: '8px' }}>
                  {t('channel.edit.wizard.previous')}
                </Button>
              )}
              {step < 3 && (
                <button
                  type='button'
                  className='aurora-save-btn'
                  onClick={() => {
                    if (step === 1 && inputs.name === '') {
                      showInfo(t('channel.edit.messages.name_required'));
                      return;
                    }
                    setStep(step + 1);
                  }}
                >
                  {t('channel.edit.wizard.next')}
                </button>
              )}
              {step === 3 && (
                <button
                  type='button'
                  className='aurora-save-btn'
                  onClick={submit}
                  disabled={loading}
                >
                  {t('channel.edit.buttons.submit')}
                </button>
              )}
            </div>
          </div>
        </Card.Content>
      </Card>
    </div>
  );
};

export default EditChannel;
